content:
:root {
  --bg-primary: #121418;
  --bg-card: #222730;
  --bg-card-hover: #2a313d;
  --accent-gold: #d4af37;
  --accent-gold-light: #f3e5ab;
  --accent-gold-dark: #aa820a;
  --accent-cyan: #38bdf8;
  --accent-crimson: #ef4444;
  --accent-crimson-glow: rgba(239, 68, 68, 0.45);
  --text-main: #f1f5f9;
  --text-muted: #94a3b8;
  --felt-red: #991b1b;
  --felt-red-shadow: #450a0a;
  --key-white-bg: linear-gradient(to bottom, #ffffff 0%, #f8fafc 85%, #e2e8f0 100%);
  --key-white-active: linear-gradient(to bottom, #e2e8f0 0%, #cbd5e1 100%);
  --key-black-bg: linear-gradient(to bottom, #2b2b2b 0%, #171717 75%, #050505 100%);
  --key-black-active: linear-gradient(to bottom, #1f1f1f 0%, #0d0d0d 100%);
  --border-subtle: rgba(255, 255, 255, 0.08);
  --radius-sm: 6px;
  --radius-md: 10px;
  --radius-lg: 16px;
  --radius-xl: 20px;
  --shadow-key: 0 4px 6px -1px rgba(0, 0, 0, 0.4), 0 2px 4px -2px rgba(0, 0, 0, 0.3);
  --shadow-panel: 0 10px 25px -5px rgba(0, 0, 0, 0.6), 0 8px 10px -6px rgba(0, 0, 0, 0.5);
  --font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
  -webkit-tap-highlight-color: transparent;
  user-select: none;
  -webkit-user-select: none;
}

body {
  font-family: var(--font-family);
  background: var(--bg-primary);
  background-image: 
    radial-gradient(circle at 50% 0%, #1e293b 0%, transparent 65%),
    linear-gradient(to bottom, #0f172a, #090d16);
  color: var(--text-main);
  min-height: 100vh;
  display: flex;
  justify-content: center;
  align-items: center;
  padding: 16px;
  overflow-x: hidden;
}

#root {
  width: 100%;
  max-width: 900px;
  display: flex;
  justify-content: center;
}

/* アプリ全体コンテナ */
.piano-app {
  width: 100%;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 16px;
}

/* ヘッダーエリア */
.piano-header {
  text-align: center;
  margin-bottom: 4px;
}

.piano-title {
  font-size: 1.85rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  color: var(--text-main);
  background: linear-gradient(135deg, #ffffff 20%, var(--accent-gold-light) 60%, var(--accent-gold) 100%);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  margin-bottom: 4px;
}

.piano-subtitle {
  font-size: 0.85rem;
  color: var(--text-muted);
  font-weight: 400;
  letter-spacing: 0.04em;
}

/* ピアノ本体外郭 */
.piano-board {
  width: 100%;
  background: linear-gradient(180deg, #23272f 0%, #181b20 100%);
  border-radius: var(--radius-xl);
  padding: 24px;
  box-shadow: var(--shadow-panel), inset 0 1px 0 rgba(255, 255, 255, 0.1);
  border: 1px solid rgba(255, 255, 255, 0.08);
  display: flex;
  flex-direction: column;
  gap: 20px;
  position: relative;
}

/* コントロールパネル */
.controls-panel {
  display: flex;
  flex-wrap: wrap;
  gap: 14px;
  background: var(--bg-card);
  padding: 16px;
  border-radius: var(--radius-lg);
  border: 1px solid var(--border-subtle);
  align-items: center;
  justify-content: space-between;
}

.control-group {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.control-label {
  font-size: 0.75rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--text-muted);
}

/* 音色（波形）選択ボタングループ */
.waveform-group {
  display: flex;
  gap: 6px;
  background: rgba(0, 0, 0, 0.25);
  padding: 4px;
  border-radius: var(--radius-md);
  border: 1px solid var(--border-subtle);
}

.waveform-btn {
  padding: 6px 12px;
  font-size: 0.78rem;
  font-weight: 600;
  background: transparent;
  color: var(--text-muted);
  border: none;
  border-radius: var(--radius-sm);
  cursor: pointer;
  transition: all 0.18s ease;
  white-space: nowrap;
}

.waveform-btn:hover {
  color: var(--text-main);
  background: rgba(255, 255, 255, 0.05);
}

.waveform-btn-active {
  background: var(--accent-gold);
  color: #1a1a1a;
  box-shadow: 0 2px 8px rgba(212, 175, 55, 0.35);
  font-weight: 700;
}

.waveform-btn-active:hover {
  background: var(--accent-gold-light);
  color: #1a1a1a;
}

/* 音量スライダー */
.slider-control {
  display: flex;
  align-items: center;
  gap: 10px;
}

.volume-slider {
  -webkit-appearance: none;
  appearance: none;
  width: 100px;
  height: 6px;
  background: #334155;
  border-radius: 4px;
  outline: none;
  cursor: pointer;
  transition: background 0.2s;
}

.volume-slider::-webkit-slider-thumb {
  -webkit-appearance: none;
  appearance: none;
  width: 16px;
  height: 16px;
  border-radius: 50%;
  background: var(--accent-gold);
  cursor: pointer;
  box-shadow: 0 1px 4px rgba(0, 0, 0, 0.5);
  transition: transform 0.15s, background-color 0.15s;
}

.volume-slider::-moz-range-thumb {
  width: 16px;
  height: 16px;
  border-radius: 50%;
  background: var(--accent-gold);
  cursor: pointer;
  border: none;
  box-shadow: 0 1px 4px rgba(0, 0, 0, 0.5);
}

.volume-slider::-webkit-slider-thumb:hover {
  transform: scale(1.15);
  background: var(--accent-gold-light);
}

/* オクターブ設定 */
.octave-control {
  display: flex;
  align-items: center;
  gap: 8px;
  background: rgba(0, 0, 0, 0.25);
  padding: 4px 8px;
  border-radius: var(--radius-md);
  border: 1px solid var(--border-subtle);
}

.octave-btn {
  width: 28px;
  height: 28px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: #2a313d;
  color: var(--text-main);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-sm);
  font-size: 1rem;
  font-weight: 700;
  cursor: pointer;
  transition: all 0.15s ease;
}

.octave-btn:hover:not(:disabled) {
  background: #3b4455;
  color: var(--accent-gold);
}

.octave-btn:disabled {
  opacity: 0.35;
  cursor: not-allowed;
}

.octave-value {
  font-size: 0.85rem;
  font-weight: 700;
  min-width: 24px;
  text-align: center;
  color: var(--accent-gold-light);
}

/* アクションボタン群（デモ・録音・再生） */
.action-group {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
}

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  padding: 7px 14px;
  font-size: 0.8rem;
  font-weight: 600;
  border-radius: var(--radius-md);
  border: 1px solid var(--border-subtle);
  cursor: pointer;
  transition: all 0.18s ease;
}

.btn-action {
  background: #2a313d;
  color: var(--text-main);
}

.btn-action:hover {
  background: #374151;
  border-color: rgba(255, 255, 255, 0.2);
}

/* 録音ボタン */
.btn-record {
  background: rgba(239, 68, 68, 0.15);
  color: #fca5a5;
  border-color: rgba(239, 68, 68, 0.3);
}

.btn-record:hover {
  background: rgba(239, 68, 68, 0.25);
  color: #fee2e2;
}

.btn-record-active {
  background: var(--accent-crimson);
  color: #ffffff;
  border-color: var(--accent-crimson);
  animation: pulse-recording 1.2s infinite ease-in-out;
}

@keyframes pulse-recording {
  0% {
    box-shadow: 0 0 0 0 var(--accent-crimson-glow);
  }
  70% {
    box-shadow: 0 0 0 8px transparent;
  }
  100% {
    box-shadow: 0 0 0 0 transparent;
  }
}

/* 再生ボタン */
.btn-play {
  background: rgba(56, 189, 248, 0.15);
  color: #7dd3fc;
  border-color: rgba(56, 189, 248, 0.3);
}

.btn-play:hover:not(:disabled) {
  background: rgba(56, 189, 248, 0.25);
  color: #e0f2fe;
}

.btn-play:disabled {
  opacity: 0.4;
  cursor: not-allowed;
}

/* 鍵盤エリア外郭（赤フェルトクロスと影の表現） */
.keyboard-outer {
  width: 100%;
  position: relative;
  background: #0f1115;
  padding: 8px 12px 14px 12px;
  border-radius: var(--radius-lg);
  border: 1px solid rgba(255, 255, 255, 0.05);
  box-shadow: inset 0 6px 12px rgba(0, 0, 0, 0.8);
  overflow-x: auto;
  overflow-y: hidden;
  -webkit-overflow-scrolling: touch;
  scrollbar-width: thin;
  scrollbar-color: #3b4455 rgba(0, 0, 0, 0.4);
}

/* 横スクロールバーのカスタマイズ */
.keyboard-outer::-webkit-scrollbar {
  height: 6px;
}

.keyboard-outer::-webkit-scrollbar-track {
  background: rgba(0, 0, 0, 0.4);
  border-radius: 3px;
}

.keyboard-outer::-webkit-scrollbar-thumb {
  background: #3b4455;
  border-radius: 3px;
}

.keyboard-outer::-webkit-scrollbar-thumb:hover {
  background: var(--accent-gold);
}

/* 鍵盤奥の赤フェルトクロス */
.keyboard-outer::before {
  content: "";
  display: block;
  position: absolute;
  top: 8px;
  left: 12px;
  right: 12px;
  height: 5px;
  background: linear-gradient(180deg, var(--felt-red-shadow) 0%, var(--felt-red) 60%, var(--felt-red-shadow) 100%);
  border-radius: 2px 2px 0 0;
  z-index: 5;
}

/* 鍵盤コンテナ */
.keyboard-container {
  display: flex;
  position: relative;
  min-width: 620px;
  height: 220px;
  margin-top: 5px;
  touch-action: none;
}

/* 鍵盤共通スタイル */
.key {
  position: relative;
  border: none;
  cursor: pointer;
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
  align-items: center;
  padding-bottom: 12px;
  outline: none;
  touch-action: none;
  transition: transform 0.06s ease, filter 0.08s ease;
}

/* 白鍵（8鍵：ド レ ミ ファ ソ ラ シ ド） */
.key-white {
  flex: 1;
  height: 100%;
  background: var(--key-white-bg);
  border-radius: 0 0 6px 6px;
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.9),
    inset 0 -4px 6px rgba(0, 0, 0, 0.15),
    inset 2px 0 3px rgba(255, 255, 255, 0.8),
    inset -2px 0 3px rgba(0, 0, 0, 0.1),
    0 4px 6px rgba(0, 0, 0, 0.4);
  border-left: 1px solid #cbd5e1;
  border-right: 1px solid #cbd5e1;
  border-bottom: 4px solid #94a3b8;
  z-index: 1;
}

.key-white:hover {
  background: linear-gradient(to bottom, #ffffff 0%, #f1f5f9 85%, #cbd5e1 100%);
}

.key-white.key-active {
  background: var(--key-white-active);
  transform: translateY(3px);
  border-bottom-width: 1px;
  box-shadow:
    inset 0 2px 5px rgba(0, 0, 0, 0.25),
    inset 0 0 12px rgba(212, 175, 55, 0.4),
    0 1px 2px rgba(0, 0, 0, 0.3);
}

/* 黒鍵（5鍵：ド# レ# ファ# ソ# ラ#） */
.key-black {
  position: absolute;
  width: 7.2%;
  height: 60%;
  background: var(--key-black-bg);
  border-radius: 0 0 4px 4px;
  box-shadow:
    inset 1px 1px 2px rgba(255, 255, 255, 0.25),
    inset -1px -1px 2px rgba(0, 0, 0, 0.6),
    2px 5px 8px rgba(0, 0, 0, 0.7);
  border-left: 1px solid #333;
  border-right: 1px solid #111;
  border-bottom: 5px solid #000;
  z-index: 3;
}

.key-black:hover {
  background: linear-gradient(to bottom, #383838 0%, #202020 75%, #0d0d0d 100%);
}

.key-black.key-active {
  background: var(--key-black-active);
  transform: translateY(2px);
  border-bottom-width: 2px;
  box-shadow:
    inset 0 2px 5px rgba(0, 0, 0, 0.8),
    0 0 10px rgba(56, 189, 248, 0.6),
    1px 2px 4px rgba(0, 0, 0, 0.5);
}

/* 鍵盤内の文字情報ラベル */
.key-label-wrapper {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 4px;
  pointer-events: none;
}

.key-white .key-label-wrapper {
  color: #334155;
}

.key-black .key-label-wrapper {
  color: #cbd5e1;
}

.key-name {
  font-size: 0.85rem;
  font-weight: 700;
  line-height: 1;
}

.key-shortcut {
  font-size: 0.7rem;
  font-family: monospace;
  font-weight: 600;
  opacity: 0.75;
  padding: 1px 5px;
  border-radius: 3px;
  background: rgba(0, 0, 0, 0.06);
}

.key-black .key-shortcut {
  background: rgba(255, 255, 255, 0.15);
}

.key-active .key-name {
  color: var(--accent-gold-dark);
}

.key-black.key-active .key-name {
  color: var(--accent-cyan);
}

/* ステータスバー（演奏音表示など） */
.status-bar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 10px 16px;
  background: var(--bg-card);
  border-radius: var(--radius-md);
  border: 1px solid var(--border-subtle);
  min-height: 48px;
}

/* 内部状態テキスト表示用（二重ネスト打ち消し・独立スタイル） */
.status-bar .status-bar,
.status-indicator {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 0;
  background: transparent;
  border: none;
  border-radius: 0;
  min-height: auto;
  font-size: 0.875rem;
  font-weight: 600;
}

.current-note-display {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 0.95rem;
  font-weight: 600;
  color: var(--accent-gold-light);
}

.current-note-display span {
  display: inline-block;
  padding: 2px 10px;
  background: rgba(212, 175, 55, 0.15);
  border: 1px solid rgba(212, 175, 55, 0.3);
  border-radius: var(--radius-sm);
  color: var(--accent-gold);
  font-weight: 700;
  min-width: 50px;
  text-align: center;
}

/* 操作説明フッターテキスト */
.helper-text {
  font-size: 0.75rem;
  color: var(--text-muted);
  text-align: center;
  line-height: 1.5;
}

/* レスポンシブ対応 */
@media (max-width: 680px) {
  body {
    padding: 8px;
  }

  .piano-title {
    font-size: 1.4rem;
  }

  .piano-board {
    padding: 14px;
    gap: 14px;
  }

  .controls-panel {
    padding: 12px;
    gap: 12px;
  }

  .keyboard-outer {
    padding: 6px 8px 10px 8px;
  }

  .keyboard-container {
    height: 190px;
  }

  .status-bar {
    flex-direction: column;
    gap: 8px;
    align-items: flex-start;
  }

  .status-bar .status-bar,
  .status-indicator {
    flex-direction: row;
    width: 100%;
  }
}

export type WaveformType = 'sine' | 'triangle' | 'sawtooth' | 'square';

export type NoteIdentifier =
  | 'C'
  | 'C#'
  | 'D'
