  note: NoteIdentifier;
  jpName: string;
  keyboardKey: string;
  isBlack: boolean;
  semiToneOffset: number;
  octaveOffset?: number;
}

export interface RecordedNote {
  note: NoteIdentifier | string;
  time: number;
  duration: number;
}

export interface DemoSongNote {
  note: NoteIdentifier;
  duration: number;
  delay: number;
  octaveOffset?: number;
}

export interface DemoSong {
  title: string;
