import { WaveformType } from './types';

let audioCtx: AudioContext | null = null;

interface ActiveVoice {
  oscillator: OscillatorNode;
  gainNode: GainNode;
}

const activeVoices = new Map<string, ActiveVoice>();

export const getAudioContext = (): AudioContext => {
  if (!audioCtx) {
    const AudioContextClass =
      window.AudioContext ||
      (window as unknown as { webkitAudioContext: typeof AudioContext }).webkitAudioContext;
    audioCtx = new AudioContextClass();
  }
  if (audioCtx.state === 'suspended') {
    audioCtx.resume().catch(() => {});
  }
  return audioCtx;
};

export const calculateFrequency = (semiToneOffset: number, octave: number): number => {
  const a4Frequency = 440;
  const a4OffsetFromC4 = 9;
  const totalOffsetFromA4 = semiToneOffset - a4OffsetFromC4 + (octave - 4) * 12;
  return a4Frequency * Math.pow(2, totalOffsetFromA4 / 12);
};

export const startTone = (
  note: string,
  frequency: number,
  waveform: WaveformType,
  volume: number
): void => {
  try {
    const ctx = getAudioContext();
    if (ctx.state === 'suspended') {
      ctx.resume().catch(() => {});
    }

    stopTone(note);

    const osc = ctx.createOscillator();
    const gainNode = ctx.createGain();

    osc.type = waveform;
    osc.frequency.setValueAtTime(frequency, ctx.currentTime);

    const targetGain = Math.max(0.0001, Math.min(1, volume));
    gainNode.gain.setValueAtTime(0.0001, ctx.currentTime);
    gainNode.gain.linearRampToValueAtTime(targetGain, ctx.currentTime + 0.015);

    osc.connect(gainNode);
    gainNode.connect(ctx.destination);

    osc.start();
    activeVoices.set(note, { oscillator: osc, gainNode });
  } catch (err) {
    console.error('Failed to start audio tone:', err);
  }
};

export const stopTone = (note: string): void => {
  const voice = activeVoices.get(note);
  if (!voice) return;

  activeVoices.delete(note);

  try {
    const ctx = getAudioContext();
    const { oscillator, gainNode } = voice;
    const releaseTime = 0.08;

    gainNode.gain.cancelScheduledValues(ctx.currentTime);
    gainNode.gain.setValueAtTime(gainNode.gain.value, ctx.currentTime);
    gainNode.gain.exponentialRampToValueAtTime(0.0001, ctx.currentTime + releaseTime);

    oscillator.stop(ctx.currentTime + releaseTime);
    oscillator.onended = () => {
      try {
        oscillator.disconnect();
        gainNode.disconnect();
      } catch {
        // 解放時の例外は無視
      }
    };
  } catch {
    // 停止時の例外は無視
  }
};

export const playTone = (
  frequency: number,
  waveform: WaveformType,
  volume: number,
  durationMs: number
): Promise<void> => {
  return new Promise((resolve) => {
    try {
      const ctx = getAudioContext();
      if (ctx.state === 'suspended') {
        ctx.resume().catch(() => {});
      }

      const osc = ctx.createOscillator();
      const gainNode = ctx.createGain();

      osc.type = waveform;
      osc.frequency.setValueAtTime(frequency, ctx.currentTime);

      const targetGain = Math.max(0.0001, Math.min(1, volume));
      const durationSec = durationMs / 1000;
      const attackSec = 0.015;
      const releaseSec = Math.min(0.1, durationSec * 0.3);
      const sustainSec = Math.max(0, durationSec - attackSec - releaseSec);

      gainNode.gain.setValueAtTime(0.0001, ctx.currentTime);
      gainNode.gain.linearRampToValueAtTime(targetGain, ctx.currentTime + attackSec);
      gainNode.gain.setValueAtTime(targetGain, ctx.currentTime + attackSec + sustainSec);
      gainNode.gain.exponentialRampToValueAtTime(0.0001, ctx.currentTime + durationSec);

      osc.connect(gainNode);
      gainNode.connect(ctx.destination);

      osc.onended = () => {
        try {
          osc.disconnect();
          gainNode.disconnect();
        } catch {
          // 解放時の例外は無視
        }
        resolve();
      };

      osc.start(ctx.currentTime);
      osc.stop(ctx.currentTime + durationSec);
    } catch (err) {
      console.error('Failed to play tone:', err);
      resolve();
    }
  });
};

export const stopAllTones = (): void => {
  const notes = Array.from(activeVoices.keys());
  for (let i = 0; i < notes.length; i++) {
    stopTone(notes[i]);
  }
};

import { FC, memo } from 'react';
import { PianoKeyItem, PIANO_KEYS } from '../types';

interface KeyboardProps {
  activeNotes?: string[];
  onNoteStart?: (note: string) => void;
  onNoteEnd?: (note: string) => void;
}

// 黒鍵の配置オフセット定義（白鍵全8鍵に対する各黒鍵の水平左位置 %）
const BLACK_KEY_POSITIONS: Record<string, string> = {
  'C#': '8.9%',
  'D#': '21.4%',
  'F#': '46.4%',
  'G#': '58.9%',
  'A#': '71.4%',
};

const getBlackKeyLeftPosition = (note: string): string => {
  return BLACK_KEY_POSITIONS[note] || '0%';
};

const Keyboard: FC<KeyboardProps> = ({
  activeNotes = [],
  onNoteStart,
  onNoteEnd,
}) => {
  const whiteKeys = PIANO_KEYS.filter((key) => !key.isBlack);
  const blackKeys = PIANO_KEYS.filter((key) => key.isBlack);

  const handlePointerDown = (item: PianoKeyItem, e: React.PointerEvent) => {
    e.preventDefault();
    onNoteStart?.(item.note);
  };

  const handlePointerUp = (item: PianoKeyItem, e: React.PointerEvent) => {
    e.preventDefault();
    onNoteEnd?.(item.note);
  };

  const handlePointerLeave = (item: PianoKeyItem, e: React.PointerEvent) => {
    e.preventDefault();
    onNoteEnd?.(item.note);
  };

  // ドラッグ操作（グリッサンド）で鍵盤に入った際、主ボタンが押されていれば発音
  const handlePointerEnter = (item: PianoKeyItem, e: React.PointerEvent) => {
    if (e.buttons === 1) {
      e.preventDefault();
      onNoteStart?.(item.note);
    }
  };

  return (
    <div className="keyboard-outer">
      <div className="keyboard-container">
        {/* 白鍵群の描画 */}
        {whiteKeys.map((item) => {
          const isActive = activeNotes.includes(item.note);
          const buttonClass = isActive
            ? 'key key-white key-active'
            : 'key key-white';

          return (
            <button
              key={item.note}
              type="button"
              className={buttonClass}
              aria-pressed={isActive}
              onPointerDown={(e) => handlePointerDown(item, e)}
              onPointerUp={(e) => handlePointerUp(item, e)}
              onPointerLeave={(e) => handlePointerLeave(item, e)}
              onPointerEnter={(e) => handlePointerEnter(item, e)}
              aria-label={`${item.jpName} (${item.keyboardKey})`}
            >
              <div className="key-label-wrapper">
                <span className="key-name">{item.jpName}</span>
                <span className="key-shortcut">{item.keyboardKey}</span>
              </div>
            </button>
          );
        })}

        {/* 黒鍵群の絶対配置描画 */}
        {blackKeys.map((item) => {
          const isActive = activeNotes.includes(item.note);
          const buttonClass = isActive
            ? 'key key-black key-active'
            : 'key key-black';

          return (
            <button
              key={item.note}
              type="button"
              className={buttonClass}
              style={{ left: getBlackKeyLeftPosition(item.note) }}
              aria-pressed={isActive}
              onPointerDown={(e) => handlePointerDown(item, e)}
              onPointerUp={(e) => handlePointerUp(item, e)}
              onPointerLeave={(e) => handlePointerLeave(item, e)}
              onPointerEnter={(e) => handlePointerEnter(item, e)}
              aria-label={`${item.jpName} (${item.keyboardKey})`}
            >
              <div className="key-label-wrapper">
                <span className="key-name">{item.jpName}</span>
                <span className="key-shortcut">{item.keyboardKey}</span>
              </div>
            </button>
          );
        })}
      </div>
    </div>
  );
};

export default memo(Keyboard);

import { FC, ChangeEvent } from 'react';
import { WaveformType, DEMO_SONGS } from '../types';

interface ControlsProps {
  waveform: WaveformType;
  volume: number;
  octave: number;
  isRecording: boolean;
  isPlayingRecorded: boolean;
  hasRecordedNotes: boolean;
  isPlayingDemo: boolean;
  onWaveformChange?: (waveform: WaveformType) => void;
  onVolumeChange?: (volume: number) => void;
  onOctaveChange?: (octave: number) => void;
  onToggleRecording?: () => void;
  onPlayRecording?: () => void;
  onPlayDemo?: (demoIndex: number) => void;
  onStopDemo?: () => void;
}

const MIN_OCTAVE = 2;
const MAX_OCTAVE = 6;
const MIN_VOLUME = 0.05;
const MAX_VOLUME = 1;
const VOLUME_STEP = 0.05;

const WAVEFORMS: { type: WaveformType; label: string }[] = [
  { type: 'sine', label: 'サイン波' },
  { type: 'triangle', label: '三角波' },
  { type: 'sawtooth', label: 'ノコギリ波' },
  { type: 'square', label: '矩形波' },
];

const Controls: FC<ControlsProps> = ({
  waveform,
  volume,
  octave,
  isRecording,
  isPlayingRecorded,
  hasRecordedNotes,
  isPlayingDemo,
  onWaveformChange,
  onVolumeChange,
  onOctaveChange,
  onToggleRecording,
  onPlayRecording,
  onPlayDemo,
  onStopDemo,
}) => {
  const handleVolumeInput = (e: ChangeEvent<HTMLInputElement>) => {
    onVolumeChange?.(parseFloat(e.target.value));
  };

  const handleOctaveDown = () => {
    if (octave > MIN_OCTAVE) {
      onOctaveChange?.(octave - 1);
    }
  };

  const handleOctaveUp = () => {
    if (octave < MAX_OCTAVE) {
      onOctaveChange?.(octave + 1);
    }
  };

  const recordBtnClass = isRecording
    ? 'btn btn-record btn-record-active'
    : 'btn btn-record';

  // オクターブボタン無効化理由
  const octaveDownDisabled = octave <= MIN_OCTAVE || isPlayingDemo;
  const octaveDownTitle = isPlayingDemo
    ? 'デモ演奏中はオクターブを変更できません'
    : octave <= MIN_OCTAVE
    ? `最低オクターブ (C${MIN_OCTAVE}) です`
    : 'オクターブを下げる';

  const octaveUpDisabled = octave >= MAX_OCTAVE || isPlayingDemo;
  const octaveUpTitle = isPlayingDemo
    ? 'デモ演奏中はオクターブを変更できません'
    : octave >= MAX_OCTAVE
    ? `最高オクターブ (C${MAX_OCTAVE}) です`
    : 'オクターブを上げる';

  // デモボタン無効化理由
  const demoDisabled = isRecording || isPlayingRecorded;
  const demoDisabledTitle = isRecording
    ? '録音中はデモ曲を再生できません'
    : isPlayingRecorded
    ? '録音音源の再生中はデモ曲を再生できません'
    : undefined;

  // 録音ボタン無効化理由
  const recordDisabled = isPlayingDemo || isPlayingRecorded;
  const recordTitle = isPlayingDemo
    ? 'デモ演奏中は録音できません'
    : isPlayingRecorded
    ? '録音音源の再生中は録音できません'
    : isRecording
    ? '録音を停止'
    : '演奏を録音';

  // 録音再生ボタン無効化理由
  const playDisabled =
    !hasRecordedNotes || isRecording || isPlayingRecorded || isPlayingDemo;
  const playTitle = !hasRecordedNotes
    ? '録音データがありません'
    : isRecording
    ? '録音中は再生できません'
    : isPlayingDemo
    ? 'デモ演奏中は再生できません'
    : isPlayingRecorded
    ? '再生中...'
    : '録音した演奏を再生';

  return (
    <div className="controls-panel">
      {/* 音色（波形）選択 */}
      <div className="control-group">
        <span className="control-label">音色</span>
        <div className="waveform-group">
          {WAVEFORMS.map((wf) => {
            const isActive = waveform === wf.type;
            const btnClass = isActive
              ? 'waveform-btn waveform-btn-active'
              : 'waveform-btn';

            return (
              <button
                key={wf.type}
                type="button"
                className={btnClass}
                onClick={() => onWaveformChange?.(wf.type)}
              >
                {wf.label}
              </button>
            );
          })}
        </div>
      </div>

      {/* 音量調整 */}
      <div className="control-group">
        <span className="control-label">音量 ({Math.round(volume * 100)}%)</span>
        <div className="slider-control">
          <input
            type="range"
            min={MIN_VOLUME}
            max={MAX_VOLUME}
            step={VOLUME_STEP}
            value={volume}
            onChange={handleVolumeInput}
            className="volume-slider"
            aria-label="音量"
            aria-valuemin={MIN_VOLUME}
            aria-valuemax={MAX_VOLUME}
            aria-valuenow={volume}
          />
        </div>
      </div>

      {/* オクターブ切り替え */}
      <div className="control-group">
        <span className="control-label">オクターブ</span>
        <div className="octave-control">
          <button
            type="button"
            className="octave-btn"
            onClick={handleOctaveDown}
            disabled={octaveDownDisabled}
            title={octaveDownTitle}
            aria-label="オクターブ下げる"
          >
            -
          </button>
          <span className="octave-value">C{octave}</span>
          <button
            type="button"
            className="octave-btn"
            onClick={handleOctaveUp}
            disabled={octaveUpDisabled}
            title={octaveUpTitle}
            aria-label="オクターブ上げる"
          >
            +
          </button>
        </div>
      </div>

      {/* デモ曲＆録音再生アクション */}
      <div className="control-group">
        <span className="control-label">機能 / 演奏</span>
        <div className="action-group">
          {isPlayingDemo ? (
            <button
              type="button"
              className="btn btn-action"
              onClick={onStopDemo}
              title="デモ演奏を停止"
            >
              停止
            </button>
          ) : (
            DEMO_SONGS.map((song, index) => (
              <button
                key={song.title}
                type="button"
                className="btn btn-action"
                disabled={demoDisabled}
                title={demoDisabled ? demoDisabledTitle : `${song.title}を再生`}
                onClick={() => onPlayDemo?.(index)}
              >
                {song.title}
              </button>
            ))
          )}

          {/* 録音ボタン */}
          <button
            type="button"
            className={recordBtnClass}
            onClick={onToggleRecording}
            disabled={recordDisabled}
            title={recordTitle}
          >
            {isRecording ? '録音中...' : '録音'}
          </button>

          {/* 録音演奏の再生ボタン */}
          <button
            type="button"
            className="btn btn-play"
            onClick={onPlayRecording}
            disabled={playDisabled}
            title={playTitle}
          >
            {isPlayingRecorded ? '再生中...' : '再生'}
          </button>
        </div>
      </div>
    </div>
  );
};

export default Controls;

import { useState, useEffect, useRef, useCallback } from 'react';
import {
  WaveformType,
  RecordedNote,
  PIANO_KEYS,
  DEMO_SONGS,
} from './types';
import {
  calculateFrequency,
  startTone,
  stopTone,
  stopAllTones,
  playTone,
} from './audio';
import Keyboard from './components/Keyboard';
import Controls from './components/Controls';
import './index.css';

interface NotePressState {
  startTime: number;
}

const App = () => {
  const [waveform, setWaveform] = useState<WaveformType>('sine');
  const [volume, setVolume] = useState<number>(0.3);
  const [octave, setOctave] = useState<number>(4);
  const [activeNotes, setActiveNotes] = useState<string[]>([]);
  const [currentNoteDisplay, setCurrentNoteDisplay] = useState<string>('なし');

  // 録音・デモ再生状態
  const [isRecording, setIsRecording] = useState<boolean>(false);
  const [recordedNotes, setRecordedNotes] = useState<RecordedNote[]>([]);
  const [isPlayingRecorded, setIsPlayingRecorded] = useState<boolean>(false);
  const [isPlayingDemo, setIsPlayingDemo] = useState<boolean>(false);

  // 録音追跡用 Ref
  const recordingStartTimeRef = useRef<number>(0);
  const notePressMapRef = useRef<Map<string, NotePressState>>(new Map());
  const activeNotesRef = useRef<string[]>([]);
  const currentRecordedNotesRef = useRef<RecordedNote[]>([]);
  const demoTimeoutsRef = useRef<number[]>([]);

  // 最新ステートを Ref に保持
  const waveformRef = useRef<WaveformType>(waveform);
  waveformRef.current = waveform;
  const volumeRef = useRef<number>(volume);
  volumeRef.current = volume;
  const octaveRef = useRef<number>(octave);
  octaveRef.current = octave;
  const isRecordingRef = useRef<boolean>(isRecording);
  isRecordingRef.current = isRecording;

  // オクターブ変更ハンドラ（音高不整合防止のため発音中ノートをリセット）
  const handleOctaveChange = useCallback((newOctave: number) => {
    stopAllTones();
    activeNotesRef.current = [];
    setActiveNotes([]);
    setCurrentNoteDisplay('なし');
    setOctave(newOctave);
  }, []);

  // ノート発音開始処理
  const handleNoteStart = useCallback((note: string) => {
    const keyItem = PIANO_KEYS.find((k) => k.note === note);
    if (!keyItem) return;

    if (!activeNotesRef.current.includes(note)) {
      activeNotesRef.current = [...activeNotesRef.current, note];
      setActiveNotes([...activeNotesRef.current]);
    }

    const freq = calculateFrequency(keyItem.semiToneOffset, octaveRef.current);
    startTone(note, freq, waveformRef.current, volumeRef.current);
    setCurrentNoteDisplay(`${keyItem.jpName} (C${octaveRef.current})`);

    // 録音トラッキング
    if (isRecordingRef.current) {
      if (!notePressMapRef.current.has(note)) {
        notePressMapRef.current.set(note, {
          startTime: Date.now() - recordingStartTimeRef.current,
        });
      }
    }
  }, []);

  // ノート発音終了処理
  const handleNoteEnd = useCallback((note: string) => {
    stopTone(note);

    activeNotesRef.current = activeNotesRef.current.filter((n) => n !== note);
    setActiveNotes([...activeNotesRef.current]);

    if (activeNotesRef.current.length === 0) {
      setCurrentNoteDisplay('なし');
    } else {
      const lastNote = activeNotesRef.current[activeNotesRef.current.length - 1];
      const item = PIANO_KEYS.find((k) => k.note === lastNote);
      if (item) {
        setCurrentNoteDisplay(`${item.jpName} (C${octaveRef.current})`);
      }
    }

    // 録音ノート確定
    if (isRecordingRef.current && notePressMapRef.current.has(note)) {
      const press = notePressMapRef.current.get(note)!;
      notePressMapRef.current.delete(note);
      const currentTime = Date.now() - recordingStartTimeRef.current;
      const duration = Math.max(100, currentTime - press.startTime);

      currentRecordedNotesRef.current.push({
        note,
        time: press.startTime,
        duration,
      });
      setRecordedNotes([...currentRecordedNotesRef.current]);
    }
  }, []);

  // PCキーボードイベントの監視
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.repeat || e.ctrlKey || e.altKey || e.metaKey) return;
      const keyChar = e.key.toUpperCase();
      const targetItem = PIANO_KEYS.find((k) => k.keyboardKey === keyChar);
      if (targetItem) {
        e.preventDefault();
        handleNoteStart(targetItem.note);
      }
    };

    const handleKeyUp = (e: KeyboardEvent) => {
      const keyChar = e.key.toUpperCase();
      const targetItem = PIANO_KEYS.find((k) => k.keyboardKey === keyChar);
      if (targetItem) {
        e.preventDefault();
        handleNoteEnd(targetItem.note);
      }
    };

    window.addEventListener('keydown', handleKeyDown);
    window.addEventListener('keyup', handleKeyUp);

    return () => {
      window.removeEventListener('keydown', handleKeyDown);
      window.removeEventListener('keyup', handleKeyUp);
    };
  }, [handleNoteStart, handleNoteEnd]);

  // デモ再生のクリア
  const clearDemoTimeouts = () => {
    demoTimeoutsRef.current.forEach((t) => clearTimeout(t));
    demoTimeoutsRef.current = [];
    stopAllTones();
    activeNotesRef.current = [];
    setActiveNotes([]);
    setIsPlayingDemo(false);
    setIsPlayingRecorded(false);
  };

  // デモ曲再生
  const handlePlayDemo = (demoIndex: number) => {
    clearDemoTimeouts();
    const song = DEMO_SONGS[demoIndex];
    if (!song) return;

    setIsPlayingDemo(true);
    let maxEndTime = 0;

    song.notes.forEach((item) => {
      const keyItem = PIANO_KEYS.find((k) => k.note === item.note);
      if (!keyItem) return;

      const freq = calculateFrequency(keyItem.semiToneOffset, octaveRef.current);
      const endTime = item.delay + item.duration;
      if (endTime > maxEndTime) {
        maxEndTime = endTime;
      }

      // 発音開始タイマー
      const startTimer = window.setTimeout(() => {
        activeNotesRef.current = [...activeNotesRef.current, item.note];
        setActiveNotes([...activeNotesRef.current]);
        setCurrentNoteDisplay(`${keyItem.jpName} (C${octaveRef.current})`);
        playTone(freq, waveformRef.current, volumeRef.current, item.duration);
      }, item.delay);

      // 視覚的終了タイマー
      const endTimer = window.setTimeout(() => {
        activeNotesRef.current = activeNotesRef.current.filter((n) => n !== item.note);
        setActiveNotes([...activeNotesRef.current]);
      }, item.delay + item.duration);

      demoTimeoutsRef.current.push(startTimer, endTimer);
    });

    // 演奏終了タイマー
    const finishTimer = window.setTimeout(() => {
      setIsPlayingDemo(false);
      setCurrentNoteDisplay('なし');
    }, maxEndTime + 100);

    demoTimeoutsRef.current.push(finishTimer);
  };

  // 録音トグル
  const handleToggleRecording = () => {
    if (isRecording) {
      // 録音停止
      setIsRecording(false);
      isRecordingRef.current = false;
      // 押しっぱなしだった音の清算
      const currentTime = Date.now() - recordingStartTimeRef.current;
      notePressMapRef.current.forEach((press, note) => {
        currentRecordedNotesRef.current.push({
          note,
          time: press.startTime,
          duration: Math.max(100, currentTime - press.startTime),
        });
      });
      notePressMapRef.current.clear();
      setRecordedNotes([...currentRecordedNotesRef.current]);
    } else {
      // 録音開始
      clearDemoTimeouts();
      currentRecordedNotesRef.current = [];
      setRecordedNotes([]);
      notePressMapRef.current.clear();
      recordingStartTimeRef.current = Date.now();
      setIsRecording(true);
      isRecordingRef.current = true;
    }
  };

  // 録音演奏の再生
  const handlePlayRecording = () => {
    if (recordedNotes.length === 0) return;
    clearDemoTimeouts();
    setIsPlayingRecorded(true);

    let maxEndTime = 0;

    recordedNotes.forEach((rn) => {
      const keyItem = PIANO_KEYS.find((k) => k.note === rn.note);
      if (!keyItem) return;

      const freq = calculateFrequency(keyItem.semiToneOffset, octaveRef.current);
      const endTime = rn.time + rn.duration;
      if (endTime > maxEndTime) {
        maxEndTime = endTime;
      }

      const startTimer = window.setTimeout(() => {
        activeNotesRef.current = [...activeNotesRef.current, rn.note];
        setActiveNotes([...activeNotesRef.current]);
        setCurrentNoteDisplay(`${keyItem.jpName} (C${octaveRef.current})`);
        playTone(freq, waveformRef.current, volumeRef.current, rn.duration);
      }, rn.time);

      const endTimer = window.setTimeout(() => {
        activeNotesRef.current = activeNotesRef.current.filter((n) => n !== rn.note);
        setActiveNotes([...activeNotesRef.current]);
      }, rn.time + rn.duration);

      demoTimeoutsRef.current.push(startTimer, endTimer);
    });

    const finishTimer = window.setTimeout(() => {
      setIsPlayingRecorded(false);
      setCurrentNoteDisplay('なし');
    }, maxEndTime + 100);

    demoTimeoutsRef.current.push(finishTimer);
  };

  // アンマウント時の停止処理
  useEffect(() => {
    return () => {
      clearDemoTimeouts();
    };
  }, []);

  return (
    <div className="piano-app">
      {/* タイトル部 */}
      <header className="piano-header">
        <h1 className="piano-title">Web ピアノ</h1>
        <p className="piano-subtitle">
          Web Audio API による本格シンセシス・1オクターブ鍵盤
        </p>
      </header>

      {/* ピアノ本体外郭 */}
      <main className="piano-board">
        {/* 操作パネル */}
        <Controls
          waveform={waveform}
          volume={volume}
          octave={octave}
          isRecording={isRecording}
          isPlayingRecorded={isPlayingRecorded}
          hasRecordedNotes={recordedNotes.length > 0}
          isPlayingDemo={isPlayingDemo}
          onWaveformChange={setWaveform}
          onVolumeChange={setVolume}
          onOctaveChange={handleOctaveChange}
          onToggleRecording={handleToggleRecording}
          onPlayRecording={handlePlayRecording}
          onPlayDemo={handlePlayDemo}
          onStopDemo={clearDemoTimeouts}
        />

        {/* 鍵盤エリア */}
        <Keyboard
          activeNotes={activeNotes}
          onNoteStart={handleNoteStart}
          onNoteEnd={handleNoteEnd}
        />

        {/* ステータスバー */}
        <div className="status-bar">
          <div className="current-note-display">
            現在の音: <span>{currentNoteDisplay}</span>
          </div>
          <div className="status-indicator">
            {isRecording && <span style={{ color: '#ef4444' }}>● 録音中...</span>}
            {isPlayingRecorded && (
              <span style={{ color: '#38bdf8' }}>▶ 録音音源を再生中</span>
            )}
            {isPlayingDemo && (
              <span style={{ color: '#d4af37' }}>♫ デモ曲を演奏中</span>
            )}
            {!isRecording && !isPlayingRecorded && !isPlayingDemo && (
              <span style={{ color: '#94a3b8' }}>待機中</span>
            )}
          </div>
        </div>

        {/* 操作ヘルプテキスト */}
        <p className="helper-text">
          PCキーボード：白鍵 [A S D F G H J K] / 黒鍵 [W E T Y U] で即座に演奏できます。
          <br />
          マウスのクリック・ドラッグやスマートフォンのタッチ操作にも完全対応しています。
        </p>
      </main>
    </div>
  );
};

export default App;
